package com.procurement.approvalstage.specification; import com.procurement.approvalstage.entity.ApprovalStage; import org.springframework.data.jpa.domain.Specification;
public final class ApprovalStageSpecification{private ApprovalStageSpecification(){}public static Specification<ApprovalStage> search(Long ruleId,Long roleId,Boolean active){return (r,q,b)->{var p=b.conjunction();if(ruleId!=null)p=b.and(p,b.equal(r.get("approvalRule").get("id"),ruleId));if(roleId!=null)p=b.and(p,b.equal(r.get("approverRole").get("id"),roleId));if(active!=null)p=b.and(p,b.equal(r.get("active"),active));return p;};}}
